const $=id=>document.getElementById(id),cell=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
try{const response=await fetch('assets/quality-v62-2.json');if(!response.ok)throw Error('The measured report has not been published yet.');const r=await response.json();if(!r.complete)throw Error('The comparison is incomplete. Raw results are retained; no final score is shown.');const a=r.summary.candidate,b=r.summary.baseline;for(const[label,key,suffix]of [['Model requests','requests',''],['Tool/citation checks passed','accepted',' / 12'],['Rubric-matched tool choices','relevant',' / 12'],['Request errors','errors',''],['Median latency','median_ms',' ms'],['95th percentile latency','p95_ms',' ms'],['Input tokens','prompt_tokens',''],['Output tokens','completion_tokens','']]){const row=document.createElement('tr');row.append(cell('th',label),cell('td',a[key]+suffix),cell('td',b[key]+suffix));$('metrics').append(row);}for(const c of r.cases){const row=document.createElement('tr');row.append(cell('td',c.id),cell('td',c.expected_tool),...['candidate','baseline'].map(k=>cell('td',`${c[k].error||c[k].plan?.tool} · ${c[k].guard.accepted?'accepted':'rejected'} · ${c[k].task_relevant?'rubric match':'rubric mismatch'}`)));$('cases').append(row);}$('method').textContent=r.method;$('status').textContent=`Recorded ${r.recorded_at} · ${r.model} · policy ${r.policy}`;$('verdict').textContent=`Production: ${a.accepted}/12 accepted, ${a.relevant}/12 rubric matches. Baseline: ${b.accepted}/12 accepted, ${b.relevant}/12 rubric matches. ${a.relevant===b.relevant?'No measured relevance advantage in this sample.':'This small sample is directional evidence, not a general superiority claim.'}`;}catch(e){$('status').textContent=e.message;$('raw').hidden=true;}
